export function renderJson(result: GateResult, specPath: string): string {
  return JSON.stringify(
    {
      spec: specPath,
      verdict: result.verdict,
      tier: result.tier,
      findings: result.findings
    },
    null,
    2
  );
}

export function renderSummary(result: GateResult): string {
  const total = GATE_CHECKS.length;

  // Special case: if gate section is missing (structure finding)
  if (result.gateSection === null) {
    const structureFinding = result.findings.find((f) => f.checkId === 'structure' && f.severity === 'block');
    if (structureFinding) {
      return `BLOCK 0/${total}: structure`;
    }
  }

  // Count checks with block findings
  const gateCheckIds = new Set(GATE_CHECKS.map((c) => c.id));
  const blockFindings = result.findings.filter((f) => f.severity === 'block' && gateCheckIds.has(f.checkId));
  const answered = total - blockFindings.length;

  // Build summary string
  let summary = `${result.verdict} ${answered}/${total}`;

  if (blockFindings.length > 0) {
    const blockCheckIds = new Set(blockFindings.map((f) => f.checkId));
    const orderedIds = GATE_CHECKS.filter((c) => blockCheckIds.has(c.id)).map((c) => c.id);
    summary += `: ${orderedIds.join(', ')}`;
  }

  return summary;
}

