tool_use_result.originalFile:
import { Finding, GateResult, GATE_CHECKS } from './schema.js';

const VERDICT_ICON: Record<GateResult['verdict'], string> = {
  PASS: '✅',
  WARN: '⚠️',
  BLOCK: '⛔'
};

function line(finding: Finding): string {
  const icon = finding.severity === 'block' ? '⛔' : '⚠️';
  const tag = finding.source === 'agent' ? ' (smart review)' : '';
  return `${icon} [${finding.checkId}]${tag} ${finding.message}`;
}

export function renderText(result: GateResult, specPath: string): string {
  const out: string[] = [];
  out.push(`FRAI Gate - ${specPath}`);
  out.push(`Verdict: ${VERDICT_ICON[result.verdict]} ${result.verdict}`);
  if (result.tier) out.push(`Risk tier: ${result.tier}`);
  if (result.findings.length === 0) {
    out.push('All seven gate checks answered. Clear to implement.');
  } else {
    out.push('');
    for (const finding of result.findings) out.push(line(finding));
    out.push('');
    if (result.verdict === 'BLOCK') {
      out.push('BLOCK: fix the items above before implementation starts.');
    } else if (result.verdict === 'WARN') {
      out.push('WARN: the gate passes structurally, but tighten the flagged answers.');
    }
  }
  return out.join('\n');
}

export function renderJson(result: GateResult, specPath: string): string {
  return JSON.stringify(
    {
      spec: specPath,
      verdict: result.verdict,
      tier: result.tier,
      findings: result.findings
    },
    null,
    2
  );
}

export function renderSummary(result: GateResult): string {
  const total = GATE_CHECKS.length;

  // Special case: if gate section is missing (structure finding)
  if (result.gateSection === null) {
    const structureFinding = result.findings.find((f) => f.checkId === 'structure' && f.severity === 'block');
    if (structureFinding) {
      return `BLOCK 0/${total}: structure`;
    }
  }

  // Count checks with block findings
  const gateCheckIds = new Set(GATE_CHECKS.map((c) => c.id));
  const blockFindings = result.findings.filter((f) => f.severity === 'block' && gateCheckIds.has(f.checkId));
  const answered = total - blockFindings.length;

  // Build summary string
  let summary = `${result.verdict} ${answered}/${total}`;

  if (blockFindings.length > 0) {
    const blockCheckIds = new Set(blockFindings.map((f) => f.checkId));
    const orderedIds = GATE_CHECKS.filter((c) => blockCheckIds.has(c.id)).map((c) => c.id);
    summary += `: ${orderedIds.join(', ')}`;
  }

  return summary;
}
